.ds-search-box {display: flex;
  align-items: center;
  gap: 14px;
  min-height: 56px;
  border: 1px solid #747d88;
  border-radius: 4px;
  padding-inline: 16px;
  flex: 1;
  max-width: 720px;}
.ds-search-box:focus-within {outline: 3px solid #2d2f91;
  outline-offset: 3px;}
.ds-search-box input {border: 0;
  outline: 0;
  background: transparent;
  width: 100%;
  height: 54px;
  min-width: 0;
  font-size: 17px;}
.ds-search-box input:focus-visible {outline: 0;}
.ds-search-box input::-webkit-search-cancel-button {display: none;}
.ds-search-box{font-family:"Barlow",sans-serif;color:#17202a;background:#fff;} .ds-search-box input{font-family:"Barlow",sans-serif;color:#17202a;}

.ds-enquiry-form {background: #f4f5f6;
  padding: 40px;}
.ds-enquiry-form > p {margin-top: 16px;
  margin-bottom: 28px;}
.ds-enquiry-form h2 {font-size: 36px;}
.ds-enquiry-form label {display: block;
  font-weight: 500;
  font-size: 15px;
  margin-bottom: 22px;}
.ds-enquiry-form input,
.ds-enquiry-form select,
.ds-enquiry-form textarea {width: 100%;
  border: 1px solid #747d88;
  border-radius: 3px;
  background: #fff;
  min-height: 48px;
  padding: 12px;
  margin-top: 8px;
  color: #17202a;}
.ds-enquiry-form textarea {resize: vertical;}
.ds-required {font-size: 11px;
  color: #5b6470;
  margin-left: 8px;
  font-weight: 400;}
.ds-enquiry-form .ds-field-hint {font-size: 13px;
  margin-top: -12px;
  margin-bottom: 24px;}
.ds-enquiry-form .ds-privacy {margin-top: 16px;
  margin-bottom: 0;
  font-size: 12px;}
.ds-enquiry-form{font-family:"Barlow",sans-serif;color:#17202a;} .ds-enquiry-form input{font-family:"Barlow",sans-serif;} .ds-enquiry-form input:focus-visible {outline:3px solid #2d2f91;outline-offset:4px;}

.ds-main-nav {display: flex;
  align-items: center;
  gap: 32px;
  font-size: 15px;
  font-weight: 500;}
.ds-main-nav > a:not(.ds-button) {padding-block: 15px;
  border-bottom: 2px solid transparent;}
.ds-main-nav > a[aria-current="page"]:not(.ds-button) {border-color: var(--action, #c81520);}
.ds-main-nav > a:hover {color: var(--action, #c81520);}
.ds-main-nav{font-family:"Barlow",sans-serif;color:#17202a;flex-wrap:wrap;} .ds-main-nav a{text-decoration:none;color:inherit;} .ds-main-nav a:focus-visible {outline:3px solid #2d2f91;outline-offset:4px;}

.ds-filter-pill {min-height: 44px;
  border: 1px solid #c81520;
  background: #fff0f0;
  color: #a9111b;
  border-radius: 30px;
  padding: 9px 13px;
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 13px;
  max-width: 100%;
  text-align: start;}
.ds-filter-pill:hover {background: #fce0e0;}
.ds-filter-pill svg {flex-shrink: 0;}
.ds-filter-pill{font-family:"Barlow",sans-serif;cursor:pointer;} .ds-filter-pill:focus-visible {outline:3px solid #2d2f91;outline-offset:4px;}

.ds-text-link {display: inline-flex;
  gap: 12px;
  align-items: center;
  font-weight: 600;
  border-bottom: 1px solid #17202a;
  padding-block: 8px;
  line-height: 1.35;}
.ds-text-link:hover {color: var(--action, #c81520);
  border-color: var(--action, #c81520);}
.ds-company-copy > .ds-text-link {margin-top: 24px;}
.ds-product-card {min-width: 0;
  border: 1px solid var(--line, #d7dce1);
  background: #fff;
  display: flex;
  flex-direction: column;
  border-radius: 4px;
  overflow: hidden;}
.ds-product-card:hover {border-color: #9099a3;}
.ds-product-image {position: relative;
  aspect-ratio: 4/3;
  background: #f5f6f7;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;}
.ds-product-image > img {width: 100%;
  height: 100%;
  object-fit: contain;
  padding: 20px;
  mix-blend-mode: multiply;}
.ds-image-note {position: absolute;
  bottom: 10px;
  left: 12px;
  right: 12px;
  font-size: 11px;
  color: #5b6470;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: #f5f6f7;}
.ds-product-card-body {padding: 22px;
  display: flex;
  flex-direction: column;
  flex: 1;}
.ds-metadata {font-size: 12px;
  color: #5b6470;
  font-weight: 500;
  margin-bottom: 10px;}
.ds-product-card h3 {font-size: 24px;
  line-height: 1.18;
  overflow-wrap: anywhere;}
.ds-product-card h3 a:hover {color: var(--action, #c81520);}
.ds-product-meta {font-size: 12px;
  margin-top: 16px;
  margin-bottom: 24px;}
.ds-product-meta span {padding-inline: 5px;}
.ds-product-card .ds-text-link {font-size: 14px;
  margin-top: auto;
  align-self: flex-start;}
.ds-not-found .ds-text-link {margin-left: 24px;}
.ds-product-card{font-family:"Barlow",sans-serif;color:#17202a;max-width:360px;} .ds-product-card p,.ds-product-card h3{margin:0;} .ds-product-card p{color:var(--muted,#5b6470);} .ds-product-card h3{font-family:"Barlow Condensed",sans-serif;font-weight:600;} .ds-product-card a{color:inherit;text-decoration:none;} .ds-product-card h3 + .ds-metadata{margin-top:12px;margin-bottom:0;} .ds-product-image>svg{width:100%;height:100%;} .ds-product-card a:focus-visible {outline:3px solid #2d2f91;outline-offset:4px;} .ds-product-card .ds-product-meta{margin-top:16px;margin-bottom:24px;}
